-- Run manually against pos_db; never invoked at application startup.
-- Preserves existing data.
BEGIN;
SET LOCAL lock_timeout = '10s';

CREATE TABLE IF NOT EXISTS "ServiceMode" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Type" varchar(50) NOT NULL,
    "Description" varchar(255) NOT NULL,
    CONSTRAINT "CK_ServiceMode_Type" CHECK (length(btrim("Type")) > 0)
);

-- Seed defaults
INSERT INTO "ServiceMode" ("Type", "Description") VALUES
    ('DINING', 'Dine-in services'),
    ('TAKEAWAY', 'Takeaway services'),
    ('DELIVERY', 'Delivery services')
ON CONFLICT ("Type") DO NOTHING;

COMMIT;
